package com.trough.hot;
import android.graphics.*;
import android.content.res.Resources;
import android.text.*;
import android.text.style.*;
import android.view.View;
import java.util.List;
import java.util.Set;
/** Dense wrapping event chips; raw tool text is available on expansion. */
final class NativeTraceRenderer {
 static final android.util.LruCache<String,CharSequence> PROSE=new android.util.LruCache<String,CharSequence>(512*1024){protected int sizeOf(String key,CharSequence value){return 128+2*(key.length()+value.length());}};
 static CharSequence prose(String body){CharSequence cached=PROSE.get(body);if(cached!=null)return cached;CharSequence value=RichText.render(body);PROSE.put(body,value);return value;}
 static String visibleUser(String text){if(text==null)return "";int at=text.lastIndexOf("\n\n[Trough home context: ");return at>=0&&text.endsWith("]")?text.substring(0,at):text;}
 static long renders,lastRenderNs,maxRenderNs,layouts,lastLayoutNs,maxLayoutNs;static int lastCharacters,lastRows;
 static void layoutTime(long ns){layouts++;lastLayoutNs=ns;maxLayoutNs=Math.max(maxLayoutNs,ns);}
 static java.util.Map<String,Object> metrics(){return Json.map("renders",renders,"last_render_us",lastRenderNs/1000,"max_render_us",maxRenderNs/1000,"layouts",layouts,"last_layout_us",lastLayoutNs/1000,"max_layout_us",maxLayoutNs/1000,"characters",lastCharacters,"rows",lastRows);}
 interface Toggle { void toggle(String key); }
 static CharSequence render(List<String[]> rows,String live,boolean solid,final Set<String> expanded,final Toggle toggle){
  long started=System.nanoTime();SpannableStringBuilder out=new SpannableStringBuilder();boolean chips=false;
  for(int i=0;i<rows.size();i++){
   String[] row=rows.get(i);String kind=row[0];if(kind.startsWith("work_"))continue;String value=row[1]==null?"":row[1];if("user".equals(kind))value=visibleUser(value);
   boolean tool="tool".equals(kind)||"result".equals(kind)||"error".equals(kind);
   if(tool){final String key=key(row,i);boolean open=solid&&expanded.contains(key);TraceCategory category="tool".equals(kind)?TraceCategory.call(value):TraceCategory.result(value,"error".equals(kind));int color=category.color;
    String title=(open?"⌄ ":"› ")+category.title;
    int start=out.length();out.append(title);int end=out.length();out.setSpan(new EventChip(color,solid,open,category.icon),start,end,33);out.setSpan(new ToolLink(key,toggle),start,end,33);out.append("\u200b");chips=true;
    if(open){out.append('\n');int titleStart=out.length();out.append("⌃ Close · "+category.title).append('\n');int titleEnd=out.length();out.setSpan(new ForegroundColorSpan(color),titleStart,titleEnd,33);out.setSpan(new AbsoluteSizeSpan(10,true),titleStart,titleEnd,33);out.setSpan(new StyleSpan(Typeface.BOLD),titleStart,titleEnd,33);out.setSpan(new ToolLink(key,toggle),titleStart,titleEnd-1,33);int bodyStart=out.length();out.append(limit(value,3000));int bodyEnd=out.length();out.setSpan(new ForegroundColorSpan(color),bodyStart,bodyEnd,33);out.setSpan(new AbsoluteSizeSpan(11,true),bodyStart,bodyEnd,33);out.setSpan(new TypefaceSpan("monospace"),bodyStart,bodyEnd,33);if(solid)out.setSpan(new BackgroundColorSpan(0xe0192937),bodyStart,bodyEnd,33);out.append("\n");chips=false;}
   }else{if(chips){out.append("\n");chips=false;}append(out,"user".equals(kind)?"YOU":"ASSISTANT",limit(value,1800),"user".equals(kind)?0xffd6b6ff:0xffedf4fa,solid);}
  }
  if(live!=null&&!live.isEmpty()){if(chips)out.append("\n");append(out,"ASSISTANT · LIVE",limit(live,4500),0xffedf4fa,solid);}renders++;lastRenderNs=System.nanoTime()-started;maxRenderNs=Math.max(maxRenderNs,lastRenderNs);lastCharacters=out.length();lastRows=rows.size();return out;
 }
 static java.util.Map<String,Object> checkLayout(android.app.Activity activity){
  java.util.List<String[]> rows=new java.util.ArrayList<String[]>();for(int i=0;i<6;i++){rows.add(new String[]{"tool","▸ Bash  command"+i+"\n{command}"});rows.add(new String[]{"result","Result "+i+"\nsecond line"});}
  rows.add(new String[]{"error","warning: [options] source value 8\nwarning: target value 8\n4 warnings"});final int[] taps={0};java.util.Set<String> expanded=new java.util.HashSet<String>();Toggle toggle=new Toggle(){public void toggle(String key){taps[0]++;}};CharSequence compact=render(rows,"",true,expanded,toggle);TextPaint paint=new TextPaint(3);paint.setTextSize(12*Resources.getSystem().getDisplayMetrics().density);int width=(int)(300*Resources.getSystem().getDisplayMetrics().density);
  StaticLayout packed=StaticLayout.Builder.obtain(compact,0,compact.length(),paint,width).setIncludePad(false).build();ClickableSpan[] links=((Spanned)compact).getSpans(0,compact.length(),ClickableSpan.class);if(links.length>0)tapLayout(activity,compact,((Spanned)compact).getSpanStart(links[0]));expanded.add(key(rows.get(10),10));CharSequence detail=render(rows,"",true,expanded,toggle);StaticLayout opened=StaticLayout.Builder.obtain(detail,0,detail.length(),paint,width).setIncludePad(false).build();
  ClickableSpan[] openedLinks=((Spanned)detail).getSpans(0,detail.length(),ClickableSpan.class);int beforeY=packed.getLineTop(packed.getLineForOffset(((Spanned)compact).getSpanStart(links[10]))),afterY=opened.getLineTop(opened.getLineForOffset(((Spanned)detail).getSpanStart(openedLinks[10])));
  CharSequence glass=render(rows,"",false,expanded,toggle);boolean glassCollapsed=android.text.TextUtils.equals(compact,glass);
  boolean uniqueKeys=!key(new String[]{"result","same"},1).equals(key(new String[]{"result","same"},2));tapLayout(activity,detail,detail.toString().indexOf("⌃ Close"));
  return Json.map("version",5,"time_ms",System.currentTimeMillis(),"events",rows.size(),"tap_targets",links.length,"collapsed_lines",packed.getLineCount(),"expanded_lines",opened.getLineCount(),"tap_callback",taps[0],"distinct_entry_keys",uniqueKeys,"chip_y_before",beforeY,"chip_y_after",afterY,"glass_collapsed",glassCollapsed,"passed",uniqueKeys&&glassCollapsed&&beforeY==afterY&&links.length==13&&taps[0]==2&&packed.getLineCount()<=3&&opened.getLineCount()>packed.getLineCount(),"scope","Actual Android StaticLayout and clickable spans on synthetic tool events; no live touches");
 }
 static void tapLayout(android.app.Activity activity,CharSequence value,int offset){android.widget.TextView text=new android.widget.TextView(activity);text.setTextSize(12);text.setText(value);text.setTextIsSelectable(true);installToolTouches(text);int width=(int)(300*Resources.getSystem().getDisplayMetrics().density);text.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));text.layout(0,0,width,text.getMeasuredHeight());Layout layout=text.getLayout();int line=layout.getLineForOffset(Math.max(0,offset));float x=layout.getPrimaryHorizontal(Math.max(0,offset))+3*Resources.getSystem().getDisplayMetrics().density,y=(layout.getLineTop(line)+layout.getLineBottom(line))/2f;long now=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(now,now,0,x,y,0),up=android.view.MotionEvent.obtain(now,now+20,1,x,y,0);text.dispatchTouchEvent(down);text.dispatchTouchEvent(up);down.recycle();up.recycle();}
 static String key(String[] row,int index){return row[0]+":"+(row.length>2?row[2]:String.valueOf(index))+":"+Integer.toHexString(row[1].hashCode());}
 static final class ToolLink extends ClickableSpan {final String key;final Toggle toggle;ToolLink(String k,Toggle action){key=k;toggle=action;}public void onClick(View v){toggle.toggle(key);}public void updateDrawState(TextPaint p){p.setUnderlineText(false);}}
 static CharSequence history(CharSequence body,int older,int newer,Toggle toggle){SpannableStringBuilder out=new SpannableStringBuilder();if(older>0){int start=out.length();out.append("↑ Earlier · "+older+" entries");out.setSpan(new ToolLink("@earlier",toggle),start,out.length(),33);}if(newer>0){if(out.length()>0)out.append("     ");int start=out.length();out.append("Newer ↓");out.setSpan(new ToolLink("@newer",toggle),start,out.length(),33);}if(out.length()>0){out.setSpan(new AbsoluteSizeSpan(11,true),0,out.length(),33);out.setSpan(new ForegroundColorSpan(0xffb4cfe5),0,out.length(),33);out.append('\n');}out.append(body);return out;}
 static void installToolTouches(final android.widget.TextView text){text.setOnTouchListener(new View.OnTouchListener(){ToolLink pressed;public boolean onTouch(View v,android.view.MotionEvent event){int action=event.getActionMasked();if(action==android.view.MotionEvent.ACTION_DOWN){pressed=linkAt(text,event);return pressed!=null;}if(action==android.view.MotionEvent.ACTION_UP&&pressed!=null){ToolLink hit=linkAt(text,event),old=pressed;pressed=null;if(hit!=null&&old.key.equals(hit.key))old.onClick(v);return true;}if(action==android.view.MotionEvent.ACTION_CANCEL){boolean had=pressed!=null;pressed=null;return had;}return pressed!=null;}});}
 static ToolLink linkAt(android.widget.TextView text,android.view.MotionEvent event){if(!(text.getText() instanceof Spanned)||text.getLayout()==null)return null;float x=event.getX()-text.getTotalPaddingLeft()+text.getScrollX(),y=event.getY()-text.getTotalPaddingTop()+text.getScrollY();Layout layout=text.getLayout();if(y<0||y>=layout.getHeight())return null;int line=layout.getLineForVertical((int)y);Spanned spans=(Spanned)text.getText();ToolLink[] links=spans.getSpans(layout.getLineStart(line),layout.getLineEnd(line),ToolLink.class);for(ToolLink link:links){int a=spans.getSpanStart(link),b=spans.getSpanEnd(link);if(layout.getLineForOffset(a)>line||layout.getLineForOffset(Math.max(a,b-1))<line)continue;float left=layout.getLineForOffset(a)==line?layout.getPrimaryHorizontal(a):layout.getLineLeft(line),right=layout.getLineForOffset(b)==line?layout.getPrimaryHorizontal(b):layout.getLineRight(line);if(x>=Math.min(left,right)&&x<=Math.max(left,right))return link;}return null;}
 static String limit(String text,int n){return text.length()>n?"…"+text.substring(text.length()-n):text;}
 static void append(SpannableStringBuilder out,String title,String body,int color,boolean solid){
  if(body.trim().isEmpty())return;
  int textStart=out.length();out.append(prose(body));int end=out.length();out.setSpan(new ForegroundColorSpan(color),textStart,end,33);out.setSpan(new AbsoluteSizeSpan(15,true),textStart,end,33);if(solid)out.setSpan(new BackgroundColorSpan(0xc0121d29),textStart,end,33);out.append("\n");
 }
 static final class EventChip extends ReplacementSpan {
  final int color;final boolean solid,open;final String label;final float d=1.2f*Resources.getSystem().getDisplayMetrics().density;
  EventChip(int tint,boolean opaque,boolean expanded,String display){color=tint;solid=opaque;open=expanded;label=display;}
  Paint paint(Paint source){Paint p=new Paint(source);p.setTextSize(10*d);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));return p;}
  @Override public int getSize(Paint source,CharSequence text,int start,int end,Paint.FontMetricsInt fm){Paint p=paint(source);if(fm!=null){fm.ascent=-(int)(15*d);fm.descent=(int)(4*d);fm.top=fm.ascent;fm.bottom=fm.descent;}return (int)(Math.max(20*d,p.measureText(label)+8*d));}
  @Override public void draw(Canvas canvas,CharSequence text,int start,int end,float x,int top,int y,int bottom,Paint source){Paint p=paint(source);float width=Math.max(18*d,p.measureText(label)+6*d);RectF r=new RectF(x,y-13*d,x+width,y+3*d);p.setColor(solid?0xef1a2c3d:0x441a2c3d);canvas.drawRoundRect(r,5*d,5*d,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(.7f*d);p.setColor(color);p.setAlpha(open?210:85);canvas.drawRoundRect(r,5*d,5*d,p);p.setStyle(Paint.Style.FILL);p.setAlpha(255);p.setColor(color);canvas.drawText(label,x+(width-p.measureText(label))/2,y-d,p);}
 }
}
